const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND'}).format(n),category=id=>CATEGORIES.find(c=>c.id===id),product=id=>PRODUCTS.find(p=>p.id===id);let cart={};try{const saved=JSON.parse(localStorage.getItem('tram-viet-cart')||'{}');if(saved&&typeof saved==='object')for(const [id,n] of Object.entries(saved))if(product(id)&&Number.isInteger(n)&&n>0&&n<=99)cart[id]=n;}catch{}let toastTimer;function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',3000)}function save(){try{localStorage.setItem('tram-viet-cart',JSON.stringify(cart))}catch{toast('Trình duyệt không cho phép lưu giỏ hàng. Giỏ chỉ giữ trong phiên này.')}count()}function count(){$('#count').textContent=Object.values(cart).reduce((a,b)=>a+b,0)}function add(id,n=1){if(!product(id))return;cart[id]=Math.min(99,(cart[id]||0)+n);save();toast('Đã thêm sản phẩm vào giỏ hàng')}const pic=(name,alt,extra='')=>`<img src="assets/${esc(name)}.jpg" alt="${esc(alt)}" ${extra}>`;function cards(items){return items.map(p=>`<article class="product"><a class="photo" href="#/san-pham/${p.id}" aria-label="Xem ${esc(p.name)}">${pic(p.image,p.name,'loading="lazy"')}<span class="badge">Sản phẩm mẫu</span></a><span class="tag">${category(p.category).name}</span><a href="#/san-pham/${p.id}"><h3>${p.name}</h3></a><small>${p.spec}</small><div class="price">${money(p.price)}</div><button class="btn" data-add="${p.id}">＋ Thêm vào giỏ</button></article>`).join('')}function guides(){return `<div class="guide-grid"><article class="guide"><b>01</b><h3>Thưởng hương vừa đủ</h3><p>Đặt nhang hoặc nụ trên đế chịu nhiệt, ở nơi thông thoáng. Không để vật dễ cháy gần nguồn nhiệt; luôn theo dõi khi đốt.</p></article><article class="guide"><b>02</b><h3>Giữ gìn hương mộc</h3><p>Đậy kín hộp sau khi sử dụng. Cất ở nơi khô ráo, tránh nắng trực tiếp, độ ẩm và các mùi mạnh.</p></article><article class="guide"><b>03</b><h3>Chăm sóc vòng trầm</h3><p>Dùng khăn mềm khô để lau. Hạn chế tiếp xúc với nước, nước hoa và chất tẩy rửa; cất riêng khi không đeo.</p></article></div>`}function story(){return `<div class="story"><div><span class="eyebrow">Câu chuyện thương hiệu</span><h2>Một nếp hương,<br>một miền ký ức.</h2></div><div><p>${esc(SITE.story)}</p><small>Câu chuyện đề xuất · Cần thay bằng lịch sử và giá trị thương hiệu thật.</small></div></div>`}function home(){return `<div class="wrap home"><div class="intro-strip"><span>Hương trầm trong đời sống Việt</span><span>Chậm lại một chút, cảm nhận nhiều hơn.</span></div><div class="hero"><div class="hero-copy"><span class="eyebrow">${esc(SITE.brand)} · Hương mộc, nếp Việt</span><h1>Hương trầm dịu mộc.<br><em>Nếp Việt an nhiên.</em></h1><p>Một nén hương cho nếp nhà, một chuỗi hạt cho ngày thường. Khám phá những nét đẹp giản dị từ trầm hương.</p><div class="actions"><a class="btn gold" href="#/san-pham">Khám phá sản phẩm →</a><a class="btn secondary" href="#/lien-he">Tư vấn</a></div></div><div class="hero-image">${pic('ritual','Không gian thưởng trà và hương trầm trong thiết kế tham chiếu')}</div></div><section>${story()}</section><section><div class="section-head"><h2>Danh mục hương trầm</h2><a class="text-link" href="#/san-pham">Xem tất cả →</a></div><div class="categories">${CATEGORIES.map(c=>`<a class="category" href="#/san-pham?danh-muc=${c.id}">${pic(c.image,c.name,'loading="lazy"')}<div><span>${c.name}</span><small>Khám phá →</small></div></a>`).join('')}</div></section><section><div class="section-head"><h2>Sản phẩm nổi bật</h2><a class="text-link" href="#/san-pham">Bộ sưu tập →</a></div><div class="grid">${cards(PRODUCTS.slice(0,4))}</div><p class="muted">Sản phẩm, giá và hình ảnh minh họa · Chưa áp dụng để giao dịch.</p></section><section><div class="section-head"><h2>Sử dụng & bảo quản</h2></div>${guides()}</section><section class="contact-band"><div><span class="eyebrow" style="color:var(--on-primary-container)">Lắng nghe & đồng hành</span><h2 style="margin-top:8px">Tìm hương trầm dành cho bạn</h2><p>Chọn một món quà, một nếp hương hay một vật phẩm gần gũi mỗi ngày.</p></div><a class="btn gold" href="#/lien-he">Yêu cầu tư vấn →</a></section></div>`}function listing(params){const selected=params.get('danh-muc')||'';return `<div class="page wrap"><div class="crumb"><a href="#/">Trang chủ</a> / Sản phẩm</div><div class="page-intro"><div><span class="eyebrow">Bộ sưu tập hương mộc</span><h1 style="margin-top:8px">Sản phẩm trầm hương</h1><p class="muted">Danh mục mẫu · Giá, quy cách và hình ảnh cần xác nhận.</p></div></div><div class="filters"><div class="field"><label for="search">Tìm sản phẩm</label><input type="search" id="search" placeholder="Tên sản phẩm, quy cách…" maxlength="100"></div><div class="field"><label for="category">Danh mục</label><select id="category"><option value="">Tất cả danh mục</option>${CATEGORIES.map(c=>`<option value="${c.id}" ${selected===c.id?'selected':''}>${c.name}</option>`).join('')}</select></div><div class="field"><label for="sort">Sắp xếp</label><select id="sort"><option value="default">Mặc định</option><option value="asc">Giá tăng dần</option><option value="desc">Giá giảm dần</option></select></div></div><div class="results" id="results" role="status"></div><div id="products" class="grid"></div></div>`}function filter(){const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').toLowerCase();let items=PRODUCTS.filter(p=>(!$('#category').value||p.category===$('#category').value)&&normalize(p.name+' '+p.spec).includes(normalize($('#search').value.trim())));if($('#sort').value!=='default')items.sort((a,b)=>$('#sort').value==='asc'?a.price-b.price:b.price-a.price);$('#results').textContent=`${items.length} sản phẩm`;$('#products').innerHTML=items.length?cards(items):'<div class="empty full"><h3>Chưa tìm thấy sản phẩm</h3><p>Thử tên khác hoặc chọn tất cả danh mục.</p><button class="btn secondary" id="reset" style="margin-top:16px">Xóa bộ lọc</button></div>'}function detail(p){if(!p)return missing();return `<div class="page wrap"><div class="crumb"><a href="#/">Trang chủ</a> / <a href="#/san-pham">Sản phẩm</a> / ${p.name}</div><div class="detail">${pic(p.image,p.name)}<div><span class="eyebrow">${category(p.category).name}</span><h1>${p.name}</h1><p>${p.description}</p><div class="price">${money(p.price)}</div><small>Giá minh họa · Chưa bao gồm phí vận chuyển</small><div class="specs"><div><span>Quy cách mẫu</span><strong>${p.spec}</strong></div><div><span>Xuất xứ / thành phần</span><span>Chờ thông tin thật</span></div><div><span>Hình ảnh</span><span>Tham chiếu thiết kế</span></div></div><div class="actions"><div class="quantity"><button data-detail-step="-1" aria-label="Giảm số lượng">−</button><input id="detail-qty" type="number" min="1" max="99" value="1" aria-label="Số lượng"><button data-detail-step="1" aria-label="Tăng số lượng">＋</button></div><button class="btn" data-detail-add="${p.id}">Thêm vào giỏ</button></div><a class="text-link" href="#/lien-he" style="display:inline-block;margin-top:24px">Tư vấn về sản phẩm này →</a><div class="notice">Sản phẩm mẫu. Website chưa tiếp nhận đơn hàng hoặc thanh toán.</div></div></div><section><div class="section-head"><h2>Sử dụng & bảo quản</h2></div>${guides()}</section></div>`}function cartPage(){const entries=Object.entries(cart);return `<div class="page wrap"><div class="crumb"><a href="#/">Trang chủ</a> / Giỏ hàng</div><h1 style="font-size:36px">Giỏ hàng của bạn</h1><div class="notice">Giỏ hàng lưu trên trình duyệt này. Đây là bản mẫu, chưa thể đặt hàng hoặc thanh toán.</div>${entries.length?`<div class="cart-layout"><div>${entries.map(([id,n])=>{const p=product(id);return `<article class="cart-row">${pic(p.image,p.name)}<div><a href="#/san-pham/${id}"><h3>${p.name}</h3></a><small>${money(p.price)} / sản phẩm</small><div class="quantity" style="margin-top:12px"><button data-step="${id}" data-delta="-1" aria-label="Giảm số lượng ${p.name}">−</button><input type="number" min="1" max="99" value="${n}" data-qty="${id}" aria-label="Số lượng ${p.name}"><button data-step="${id}" data-delta="1" aria-label="Tăng số lượng ${p.name}">＋</button></div></div><div><div class="price">${money(p.price*n)}</div><button class="remove" data-remove="${id}">Xóa sản phẩm</button></div></article>`}).join('')}</div><aside class="summary"><h3>Tóm tắt giỏ hàng</h3><p>Tạm tính</p><div class="price">${money(entries.reduce((s,[id,n])=>s+product(id).price*n,0))}</div><p class="muted">Phí vận chuyển và chính sách bán hàng chưa được cấu hình.</p><a class="btn" href="#/lien-he">Tư vấn về giỏ hàng →</a><a class="text-link" href="#/san-pham" style="display:block;margin-top:16px">Tiếp tục khám phá</a></aside></div>`:`<div class="empty"><h2>Giỏ hàng đang trống</h2><p>Chọn một sản phẩm để bắt đầu.</p><a class="btn" style="margin-top:24px" href="#/san-pham">Khám phá sản phẩm</a></div>`}</div>`}function consult(){return `<div class="page wrap"><div class="crumb"><a href="#/">Trang chủ</a> / Liên hệ</div><div class="consult"><div><span class="eyebrow">Kết nối với ${esc(SITE.brand)}</span><h1 style="font-size:36px;margin-top:12px">Một lời nhắn,<br>một sự đồng hành.</h1><p>Chia sẻ nhu cầu để chuẩn bị yêu cầu tư vấn về sản phẩm, quà tặng hoặc cách sử dụng.</p><div class="notice">Form minh họa chưa kết nối backend. Thông tin không được gửi đến cửa hàng, không được lưu trên máy chủ.</div><p><strong>Thông tin liên hệ</strong></p><p>${SITE.phone?`<a class="text-link" href="tel:${esc(SITE.phone)}">${esc(SITE.phone)}</a>`:'Số điện thoại: Chưa cập nhật'}<br>${SITE.email?`<a class="text-link" href="mailto:${esc(SITE.email)}">${esc(SITE.email)}</a>`:'Email: Chưa cập nhật'}<br>${esc(SITE.address)}</p><p class="muted">Cần thay bằng thông tin liên hệ thật trước khi công bố.</p></div><form id="consult" novalidate><h2 style="font-size:24px;margin-bottom:24px">Yêu cầu tư vấn</h2><div class="form-grid"><div class="field"><label for="name">Họ và tên *</label><input id="name" name="name" autocomplete="name" maxlength="80" required aria-describedby="name-error"><span class="error" id="name-error"></span></div><div class="field"><label for="phone">Số điện thoại *</label><input id="phone" name="phone" type="tel" autocomplete="tel" required aria-describedby="phone-error"><span class="error" id="phone-error"></span></div><div class="field full"><label for="email">Email (không bắt buộc)</label><input id="email" name="email" type="email" autocomplete="email" maxlength="120" aria-describedby="email-error"><span class="error" id="email-error"></span></div><div class="field full"><label for="interest">Sản phẩm quan tâm</label><select id="interest" name="interest"><option value="">Tư vấn chung</option>${CATEGORIES.map(c=>`<option>${c.name}</option>`).join('')}</select></div><div class="field full"><label for="message">Nội dung cần tư vấn *</label><textarea id="message" name="message" required maxlength="1000" placeholder="Chia sẻ nhu cầu của bạn (10–1.000 ký tự)" aria-describedby="message-error"></textarea><span class="error" id="message-error"></span></div><div class="full"><label class="check"><input id="consent" type="checkbox" aria-describedby="consent-error"><span>Tôi hiểu đây là form minh họa và thông tin chưa được gửi đi. *</span></label><span class="error" id="consent-error"></span></div></div><button class="btn" type="submit" style="margin-top:20px">Kiểm tra yêu cầu tư vấn</button><div id="form-status" role="status" aria-live="polite"></div></form></div></div>`}function missing(){return '<div class="page wrap empty"><h1>Không tìm thấy trang</h1><p>Liên kết có thể đã thay đổi.</p><a class="btn" href="#/">Về trang chủ</a></div>'}function render(){let raw=location.hash.slice(1)||'/';const [path,query]=raw.split('?'),params=new URLSearchParams(query||'');let content;if(path==='/')content=home();else if(path==='/san-pham')content=listing(params);else if(path.startsWith('/san-pham/'))content=detail(product(path.split('/')[2]));else if(path==='/gio-hang')content=cartPage();else if(path==='/lien-he')content=consult();else if(path==='/cau-chuyen')content=`<div class="page wrap"><div class="crumb"><a href="#/">Trang chủ</a> / Câu chuyện</div>${story()}<section class="contact-band"><div><h2>Hương mộc trong đời sống hôm nay</h2><p>Khám phá bộ sưu tập mẫu, từ vòng tay đến nếp hương trong nhà.</p></div><a class="btn gold" href="#/san-pham">Khám phá sản phẩm →</a></section></div>`;else if(path==='/huong-dan')content=`<div class="page wrap"><div class="crumb"><a href="#/">Trang chủ</a> / Cẩm nang</div><h1 style="font-size:36px">Sử dụng & bảo quản</h1><p>Một vài lưu ý để gìn giữ vật phẩm và sử dụng nguồn nhiệt cẩn thận.</p><section>${guides()}</section><div class="notice">Đọc thêm hướng dẫn đi kèm sản phẩm thật. Không để nhang đang cháy mà không có người theo dõi; tránh xa trẻ nhỏ và vật nuôi.</div></div>`;else content=missing();$('#main').innerHTML=content;document.querySelectorAll('[data-brand]').forEach(el=>el.textContent=SITE.brand);document.title=(path==='/san-pham'?'Sản phẩm':path==='/gio-hang'?'Giỏ hàng':path==='/lien-he'?'Liên hệ':'Hương mộc, nếp Việt')+' · '+SITE.brand;document.querySelectorAll('nav a').forEach(a=>{a.removeAttribute('aria-current');if(a.hash==='#'+path)a.setAttribute('aria-current','page')});$('#navigation').classList.remove('open');$('#menu').setAttribute('aria-expanded','false');if($('#search')){filter();$('#search').addEventListener('input',filter);$('#category').addEventListener('change',filter);$('#sort').addEventListener('change',filter)}if($('#consult'))$('#consult').addEventListener('submit',validateForm);count();window.scrollTo(0,0)}function clamp(v){return Math.max(1,Math.min(99,Math.floor(Number(v)||1)))}document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='menu'){const open=$('#navigation').classList.toggle('open');b.setAttribute('aria-expanded',String(open));b.setAttribute('aria-label',open?'Đóng menu':'Mở menu')}if(b.dataset.add)add(b.dataset.add);if(b.dataset.detailAdd){$('#detail-qty').value=clamp($('#detail-qty').value);add(b.dataset.detailAdd,Number($('#detail-qty').value))}if(b.dataset.detailStep)$('#detail-qty').value=clamp(Number($('#detail-qty').value)+Number(b.dataset.detailStep));if(b.dataset.step){cart[b.dataset.step]=clamp(cart[b.dataset.step]+Number(b.dataset.delta));save();$('#main').innerHTML=cartPage()}if(b.dataset.remove){delete cart[b.dataset.remove];save();$('#main').innerHTML=cartPage();toast('Đã xóa sản phẩm khỏi giỏ hàng')}if(b.id==='reset'){$('#search').value='';$('#category').value='';$('#sort').value='default';filter()}});document.addEventListener('change',e=>{if(e.target.dataset.qty){cart[e.target.dataset.qty]=clamp(e.target.value);save();queueMicrotask(()=>{if(location.hash==='#/gio-hang')$('#main').innerHTML=cartPage()})}if(e.target.id==='detail-qty')e.target.value=clamp(e.target.value)});document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#navigation').classList.remove('open');$('#menu').setAttribute('aria-expanded','false')}});function validateForm(e){e.preventDefault();const errors={name:$('#name').value.trim().length<2?'Nhập họ tên từ 2 ký tự.':'',phone:/^(0\d{9}|\+84\d{9})$/.test($('#phone').value.replace(/[\s().-]/g,''))?'':'Nhập số điện thoại Việt Nam hợp lệ (0… hoặc +84…).',email:$('#email').value&&!$('#email').validity.valid?'Email chưa đúng định dạng.':'',message:$('#message').value.trim().length<10?'Nhập nội dung từ 10 ký tự.':'',consent:$('#consent').checked?'':'Vui lòng xác nhận trạng thái form minh họa.'};let first;for(const [id,msg]of Object.entries(errors)){$('#'+id+'-error').textContent=msg;$('#'+id).setAttribute('aria-invalid',String(!!msg));if(msg&&!first)first=$('#'+id)}$('#form-status').className='form-status';$('#form-status').textContent=first?'Vui lòng kiểm tra các trường được đánh dấu.':'Thông tin hợp lệ. Yêu cầu CHƯA ĐƯỢC GỬI vì website chưa kết nối backend. Bạn có thể tiếp tục chỉnh sửa nội dung; không có đơn hàng hay yêu cầu tư vấn nào được tạo.';if(first)first.focus()}window.addEventListener('hashchange',render);window.addEventListener('storage',e=>{if(e.key==='tram-viet-cart'){try{const next=JSON.parse(e.newValue||'{}');cart={};if(next&&typeof next==='object')for(const[id,n]of Object.entries(next))if(product(id)&&Number.isInteger(n)&&n>0&&n<=99)cart[id]=n;count();if(location.hash==='#/gio-hang')$('#main').innerHTML=cartPage()}catch{}}});render();

